package com.securevault.controller;
import com.securevault.service.PasswordRecoveryService;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth/recovery") @CrossOrigin(origins="http://localhost:5173") public class RecoveryController{private final PasswordRecoveryService service;public RecoveryController(PasswordRecoveryService s){service=s;}@PostMapping("/request")public Map<String,Object> request(@RequestBody Map<String,String>b){String t=service.request(b.get("email"));Map<String,Object>m=new LinkedHashMap<>();m.put("message","If the account exists, recovery instructions have been generated.");if(t!=null)m.put("developmentToken",t);return m;}@PostMapping("/reset")public ResponseEntity<?> reset(@RequestBody Map<String,String>b){try{service.reset(b.get("token"),b.get("password"));return ResponseEntity.ok(Map.of("message","Password reset successfully"));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}}
